            }
        ],
        [
            {
                "role": "user",
                "content": "I prefer plant-based protein shakes after workouts.",
            }
        ],
        [{"role": "user", "content": "My resting heart rate is around 58 bpm."}],
    ]

    add_tasks = [
        client.add(
            messages=message,
            user_id=user_id,
            agent_id=agent_id,
            app_id=app_id,
            run_id=run_scope,
